params.spec:
{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Hourly activity for the current selection against its OWN pattern for that hour of day. The shaded band is their typical range for the hour (\"typical range\" in the legend, which lists only what is drawn) — the middle half of the seven observations in the window — and a point marks an hour beyond 1.5× that range, which is unusual for them. Seven observations per hour slot is thin, so read it as a sanity check rather than a detector: an identity with a steady background process plus human bursts will sit outside often, and correctly. The headline reads the last complete hour; the current partial hour is left off so it cannot read as a drop. Hours are UTC. Fixed 7-day window: does not follow the time picker. No noise gate, so it will not reconcile with Signal events. The quartiles count only hours from their first event on, so the week before their history starts does not drag the band to zero. With less than three days of history the band has nothing to stand on: it is not drawn, the second line says when their history starts, no hour is marked unusual (every busy hour would read as unusual against a week of zeros), and the time axis starts three hours before that history instead of seven days back, so the chart is not a week of empty floor with the data in a sliver at the right edge. Hours before their first event are not drawn at all: the line starts where their history does, rather than climbing from zero through every decade of the log axis as if the volume had ramped up.",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": 4,
  "config": {
    "axis": {
      "labelFontSize": 11,
      "titleFontSize": 11
    },
    "legend": {
      "labelFontSize": 11
    }
  },
  "signals": [
    {
      "name": "head",
      "value": 40
    },
    {
      "name": "quiet",
      "update": "length(data('summary')) === 0 || data('summary')[0].total === 0"
    },
    {
      "name": "xlo",
      "update": "length(data('summary')) ? (data('summary')[0].short && isValid(data('summary')[0].firstActive) ? max(data('summary')[0].firstKey, data('summary')[0].firstActive - 3 * 3600000) : data('summary')[0].firstKey) : 0"
    },
    {
      "name": "xhi",
      "update": "length(data('summary')) ? data('summary')[0].lastKey : 1"
    }
  ],
  "data": [
    {
      "name": "hours",
      "url": {
        "index": "logs-elastic_cloud.serverless_audit.otel-*",
        "body": {
          "size": 0,
          "query": {
            "bool": {
              "must": [
                "%dashboard_context-must_clause%",
                {
                  "range": {
                    "@timestamp": {
                      "gte": "now-167h/h",
                      "lte": "now"
                    }
                  }
                }
              ],
              "must_not": [
                "%dashboard_context-must_not_clause%"
              ],
              "filter": [
                "%dashboard_context-filter_clause%"
              ]
            }
          },
          "aggs": {
            "hours": {
              "date_histogram": {
                "field": "@timestamp",
                "fixed_interval": "1h",
                "time_zone": "UTC",
                "min_doc_count": 0,
                "extended_bounds": {
                  "min": "now-167h/h",
                  "max": "now"
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.hours.buckets"
      }
    },
    {
      "name": "series",
      "source": "hours",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.key + 3600000 <= now()"
        },
        {
          "type": "formula",
          "as": "events",
          "expr": "datum.doc_count"
        },
        {
          "type": "formula",
          "as": "activeKey",
          "expr": "datum.events > 0 ? datum.key : null"
        },
        {
          "type": "joinaggregate",
          "fields": [
            "activeKey",
            "key",
            "key"
          ],
          "ops": [
            "min",
            "max",
            "min"
          ],
          "as": [
            "firstActive",
            "lastKey",
            "firstKey"
          ]
        },
        {
          "type": "formula",
          "as": "short",
          "expr": "datum.lastKey - datum.firstActive < 3 * 86400000"
        },
        {
          "type": "formula",
          "as": "livedEvents",
          "expr": "datum.key >= datum.firstActive ? datum.events : null"
        },
        {
          "type": "formula",
          "as": "slot",
          "expr": "utchours(datum.key)"
        },
        {
          "type": "joinaggregate",
          "groupby": [
            "slot"
          ],
          "fields": [
            "livedEvents",
            "livedEvents",
            "livedEvents"
          ],
          "ops": [
            "q1",
            "median",
            "q3"
          ],
          "as": [
            "q1",
            "med",
            "q3"
          ]
        },
        {
          "type": "formula",
          "as": "hi",
          "expr": "datum.q3 + 1.5 * (datum.q3 - datum.q1)"
        },
        {
          "type": "formula",
          "as": "lo",
          "expr": "max(0, datum.q1 - 1.5 * (datum.q3 - datum.q1))"
        },
        {
          "type": "formula",
          "as": "flag",
          "expr": "datum.short ? 'typical' : datum.events > datum.hi ? 'unusually busy' : datum.events < datum.lo ? 'unusually quiet' : 'typical'"
        },
        {
          "type": "formula",
          "as": "out",
          "expr": "datum.flag === 'typical' ? 0 : 1"
        }
      ]
    },
    {
      "name": "shown",
      "source": "series",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.key >= xlo"
        }
      ]
    },
    {
      "name": "lived",
      "source": "shown",
      "transform": [
        {
          "type": "filter",
          "expr": "isValid(datum.firstActive) && datum.key >= datum.firstActive"
        },
        {
          "type": "formula",
          "as": "decade",
          "expr": "datum.events > 0 ? pow(10, floor(log(datum.events) / LN10 + 1e-9)) : 0"
        }
      ]
    },
    {
      "name": "outside",
      "source": "lived",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.out === 1"
        }
      ]
    },
    {
      "name": "summary",
      "source": "series",
      "transform": [
        {
          "type": "window",
          "sort": {
            "field": "key",
            "order": "descending"
          },
          "ops": [
            "row_number"
          ],
          "as": [
            "recency"
          ]
        },
        {
          "type": "formula",
          "as": "inHistory",
          "expr": "!isValid(datum.firstActive) || datum.key >= datum.firstActive"
        },
        {
          "type": "formula",
          "as": "outCounted",
          "expr": "datum.inHistory ? datum.out : 0"
        },
        {
          "type": "formula",
          "as": "hourCounted",
          "expr": "datum.inHistory ? 1 : 0"
        },
        {
          "type": "joinaggregate",
          "fields": [
            "outCounted",
            "hourCounted",
            "events"
          ],
          "ops": [
            "sum",
            "sum",
            "sum"
          ],
          "as": [
            "n_out",
            "n_hours",
            "total"
          ]
        },
        {
          "type": "filter",
          "expr": "datum.recency === 1"
        },
        {
          "type": "formula",
          "as": "line1",
          "expr": "datum.total === 0 ? 'No activity for this selection in the last 7 days' : utcFormat(datum.key, '%H:00') + ' UTC (last full hour): ' + format(datum.events, ',') + ' events' + (datum.short ? '' : ', ' + (datum.med > 0 ? format(datum.events / datum.med, '.1f') + '× their median' : 'usually an idle hour'))"
        },
        {
          "type": "formula",
          "as": "line2",
          "expr": "datum.total === 0 ? '' : datum.short ? 'History only since ' + utcFormat(datum.firstActive, '%a %H:00') + ' UTC: too short to judge, so no hour is marked unusual' : datum.n_out + ' of ' + datum.n_hours + ' hours unusual for the time of day'"
        }
      ]
    },
    {
      "name": "bandKey",
      "source": "series",
      "transform": [
        {
          "type": "filter",
          "expr": "!datum.short && datum.q3 > datum.q1"
        },
        {
          "type": "aggregate",
          "ops": [
            "count"
          ],
          "as": [
            "n"
          ]
        },
        {
          "type": "formula",
          "as": "k",
          "expr": "'typical range'"
        }
      ]
    },
    {
      "name": "flagKeys",
      "source": "outside",
      "transform": [
        {
          "type": "aggregate",
          "groupby": [
            "flag"
          ]
        },
        {
          "type": "formula",
          "as": "k",
          "expr": "datum.flag"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "x",
      "type": "utc",
      "domain": {
        "signal": "[xlo, xhi]"
      },
      "range": "width"
    },
    {
      "name": "y",
      "type": "symlog",
      "domain": {
        "data": "lived",
        "fields": [
          "events",
          "q1",
          "q3",
          "decade"
        ]
      },
      "range": [
        {
          "signal": "height"
        },
        {
          "signal": "head"
        }
      ],
      "zero": false
    },
    {
      "name": "key",
      "type": "ordinal",
      "domain": [
        "typical",
        "unusually busy",
        "unusually quiet"
      ],
      "range": [
        "#5082B1",
        "#d95926",
        "#9085e9"
      ]
    },
    {
      "name": "drawn",
      "type": "ordinal",
      "domain": {
        "fields": [
          {
            "data": "bandKey",
            "field": "k"
          },
          {
            "data": "flagKeys",
            "field": "k"
          }
        ],
        "sort": true
      },
      "range": [
        "#5082B1",
        "#d95926",
        "#9085e9"
      ]
    }
  ],
  "axes": [
    {
      "orient": "bottom",
      "scale": "x",
      "tickCount": 7,
      "labelOverlap": true,
      "labelSeparation": 10,
      "grid": false,
      "format": "%a %d",
      "formatType": "utc",
      "encode": {
        "labels": {
          "update": {
            "text": {
              "signal": "xhi - xlo < 2 * 86400000 ? utcFormat(datum.value, '%a %H:00') : utcFormat(datum.value, '%a %d')"
            }
          }
        }
      }
    },
    {
      "orient": "left",
      "scale": "y",
      "grid": true,
      "gridOpacity": 0.4,
      "values": {
        "signal": "slice([0, 10, 100, 1000, 10000, 100000, 1000000, 10000000, 100000000], domain('y')[0] <= 0 ? 0 : ceil(log(domain('y')[0]) / LN10), 2 + floor(log(max(domain('y')[1], 10)) / LN10))"
      },
      "encode": {
        "labels": {
          "update": {
            "text": {
              "signal": "format(datum.value, '~s')"
            },
            "opacity": {
              "signal": "quiet ? 0 : 1"
            }
          }
        },
        "grid": {
          "update": {
            "opacity": {
              "signal": "quiet ? 0 : 1"
            }
          }
        },
        "domain": {
          "update": {
            "opacity": {
              "signal": "quiet ? 0 : 1"
            }
          }
        },
        "ticks": {
          "update": {
            "opacity": {
              "signal": "quiet ? 0 : 1"
            }
          }
        }
      }
    }
  ],
  "legends": [
    {
      "fill": "drawn",
      "orient": "none",
      "legendX": {
        "signal": "width - 10 - 100 * length(domain('drawn'))"
      },
      "legendY": 20,
      "direction": "horizontal",
      "symbolType": "circle",
      "symbolSize": 50,
      "labelLimit": 160,
      "encode": {
        "title": {
          "update": {
            "opacity": {
              "signal": "quiet ? 0 : 1"
            }
          }
        },
        "labels": {
          "update": {
            "opacity": {
              "signal": "quiet ? 0 : 1"
            }
          }
        },
        "symbols": {
          "update": {
            "opacity": {
              "signal": "quiet ? 0 : 1"
            },
            "fill": {
              "signal": "datum.value === 'unusually busy' ? '#d95926' : datum.value === 'unusually quiet' ? '#9085e9' : '#5082B1'"
            },
            "fillOpacity": {
              "signal": "datum.value === 'typical range' ? 0.45 : 1"
            },
            "shape": {
              "signal": "datum.value === 'typical range' ? 'square' : 'circle'"
            },
            "strokeWidth": {
              "value": 0
            }
          }
        }
      }
    }
  ],
  "marks": [
    {
      "type": "area",
      "from": {
        "data": "lived"
      },
      "interactive": false,
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "key"
          },
          "y": {
            "scale": "y",
            "field": "q1"
          },
          "y2": {
            "scale": "y",
            "field": "q3"
          },
          "interpolate": {
            "value": "step-after"
          },
          "fill": {
            "value": "#5082B1"
          },
          "fillOpacity": {
            "signal": "quiet || datum.short ? 0 : 0.35"
          }
        }
      }
    },
    {
      "type": "line",
      "from": {
        "data": "lived"
      },
      "interactive": false,
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "key"
          },
          "y": {
            "scale": "y",
            "field": "events"
          },
          "stroke": {
            "value": "#3987e5"
          },
          "strokeWidth": {
            "value": 1.5
          },
          "strokeOpacity": {
            "signal": "quiet ? 0 : 1"
          }
        }
      }
    },
    {
      "type": "symbol",
      "from": {
        "data": "outside"
      },
      "interactive": false,
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "key"
          },
          "y": {
            "scale": "y",
            "field": "events"
          },
          "size": {
            "value": 42
          },
          "fill": {
            "scale": "key",
            "field": "flag"
          }
        }
      }
    },
    {
      "type": "symbol",
      "from": {
        "data": "lived"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "key"
          },
          "y": {
            "scale": "y",
            "field": "events"
          },
          "size": {
            "value": 120
          },
          "fill": {
            "value": "#3987e5"
          },
          "fillOpacity": {
            "value": 0
          },
          "tooltip": {
            "signal": "{'Hour': utcFormat(datum.key, '%a %d %b, %H:00') + ' UTC', 'Events': format(datum.events, ','), 'Typical for this hour': format(datum.q1, ',.0f') + ' – ' + format(datum.q3, ',.0f'), 'Unusual beyond': format(datum.lo, ',.0f') + ' – ' + format(datum.hi, ',.0f'), 'Reading': datum.flag}"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "summary"
      },
      "style": "guide-title",
      "interactive": false,
      "encode": {
        "update": {
          "x": {
            "value": 0
          },
          "y": {
            "value": 2
          },
          "baseline": {
            "value": "top"
          },
          "fontSize": {
            "value": 13
          },
          "fontWeight": {
            "value": 600
          },
          "text": {
            "field": "line1"
          },
          "limit": {
            "signal": "width"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "summary"
      },
      "style": "guide-label",
      "interactive": false,
      "encode": {
        "update": {
          "x": {
            "value": 0
          },
          "y": {
            "value": 20
          },
          "baseline": {
            "value": "top"
          },
          "fontSize": {
            "value": 11
          },
          "text": {
            "field": "line2"
          },
          "limit": {
            "signal": "width - 20 - 100 * length(domain('drawn'))"
          }
        }
      }
    }
  ]
}
